                        buf[::core::mem::size_of::<[c_char; 11]>() - 1] = 0;
                        unsafe { copy_cstr_to_out((&raw mut buf) as *mut c_char, &mut out) };
                        // SAFETY: advances by one byte exactly as original invalid-char path.
                        cur = unsafe { cur.add(1) };
                        continue;
                    } else {
                        snprintf(
                            &raw mut buf as *mut c_char,
                            ::core::mem::size_of::<[c_char; 11]>() as size_t,
                            b"&#x%X;\0" as *const u8 as *const c_char,
                            val,
                        );
                        buf[::core::mem::size_of::<[c_char; 11]>() - 1] = 0;
                        unsafe { copy_cstr_to_out((&raw mut buf) as *mut c_char, &mut out) };
                        // SAFETY: advances by decoded UTF-8 sequence length exactly as original.
                        cur = unsafe { cur.add(l as usize) };
                        continue;
                    }
                }
            }
        } else if (0x9 <= c && c <= 0xa) || c == 0xd || 0x20 <= c {
            let mut buf_0: [c_char; 11] = [0; 11];
            snprintf(
                &raw mut buf_0 as *mut c_char,
                ::core::mem::size_of::<[c_char; 11]>() as size_t,
                b"&#%d;\0" as *const u8 as *const c_char,
                c,
            );
            buf_0[::core::mem::size_of::<[c_char; 11]>() - 1] = 0;
            unsafe { copy_cstr_to_out((&raw mut buf_0) as *mut c_char, &mut out) };
        }

        // SAFETY: advance one byte in the NUL-terminated input, matching original loop.
        cur = unsafe { cur.add(1) };
    }

    // SAFETY: output buffer always has at least the reserved slack; writing the terminator is in-bounds.
    unsafe {
        *out = 0;
    }
    buffer
}
